cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
  <style>
    :root {
      --bg: oklch(98.5% 0.004 255);
      --surface: oklch(100% 0 0);
      --surface-2: oklch(97% 0.004 255);
      --border: oklch(90% 0.01 255);
      --text: oklch(26% 0.02 260);
      --muted: oklch(53% 0.02 255);
      --brand: oklch(58% 0.2 258);
      --brand-2: oklch(64% 0.17 250);
      --positive: oklch(71% 0.19 154);
      --negative: oklch(62% 0.22 23);
      --warning: oklch(74% 0.15 85);
      --shadow: 0 1px 2px rgba(17,24,39,0.06), 0 8px 24px rgba(17,24,39,0.05);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; background: var(--bg); color: var(--text); }
    body { font-family: Inter, "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }

    .num, .pct, .mono { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1; }

    .container { width: min(1680px, calc(100% - 28px)); margin: 0 auto; }

    .topbar {
      border-bottom: 1px solid var(--border);
      background: var(--surface);
      position: sticky;
      top: 0;
      z-index: 20;
    }

    .topbar-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      height: 64px;
    }

    .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; }
    .logo {
      width: 30px; height: 30px; border-radius: 7px;
      background: linear-gradient(135deg, var(--brand), var(--brand-2));
      color: #fff; display: grid; place-items: center; font-size: 13px;
    }
    .brand span { font-size: 18px; letter-spacing: -0.01em; }

    .nav { display: flex; align-items: center; gap: 16px; }
    .nav a {
      text-decoration: none; color: var(--muted); font-weight: 600; font-size: 14px;
      padding: 8px 10px; border-radius: 8px;
    }
    .nav a:hover, .nav a.active { color: var(--text); background: var(--surface-2); }

    .market-strip {
      border-bottom: 1px solid var(--border);
      background: var(--surface);
      font-size: 13px;
    }
    .market-strip .container {
      display: flex; align-items: center; gap: 16px; flex-wrap: wrap; padding: 10px 0;
    }
    .stat-item { color: var(--muted); }
    .stat-item b { color: var(--text); font-weight: 650; }
    .up { color: var(--positive); }
    .down { color: var(--negative); }

    .promo-wrap { margin: 14px 0 10px; }
    .promo {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: var(--shadow);
      overflow: hidden;
      position: relative;
      height: 92px;
      display: flex;
      align-items: stretch;
    }
    .slides { display: flex; width: 100%; transition: transform .4s ease; }
    .slide {
      min-width: 100%;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 18px;
      background: linear-gradient(90deg, oklch(97% 0.03 255), oklch(99% 0.01 255));
    }
    .slide h3 { margin: 0 0 4px; font-size: 18px; }
    .slide p { margin: 0; color: var(--muted); font-size: 13px; }
    .slide .cta {
      border: 1px solid var(--brand);
      color: var(--brand);
      background: white;
      border-radius: 10px;
      padding: 9px 14px;
      font-weight: 650;
      cursor: pointer;
    }
    .arrow {
      position: absolute; top: 50%; transform: translateY(-50%);
      width: 30px; height: 30px; border-radius: 50%; border: 1px solid var(--border);
      background: rgba(255,255,255,.95); cursor: pointer; color: var(--text);
    }
    .arrow.left { left: 10px; }
    .arrow.right { right: 10px; }

    .ai-alert {
      margin: 8px 0 14px;
      border: 1px solid oklch(88% 0.05 250);
      background: oklch(98% 0.02 250);
      border-radius: 10px;
      padding: 11px 14px;
      display: flex; align-items: center; gap: 10px;
      font-size: 13px;
    }

    .panel {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: var(--shadow);
    }

    .table-head { padding: 14px; border-bottom: 1px solid var(--border); }
    .title-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
    h1 { margin: 0; font-size: 26px; letter-spacing: -0.02em; }
    .sub { margin: 4px 0 0; color: var(--muted); font-size: 13px; }

    .chip-row { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
    .chip {
      border: 1px solid var(--border);
      background: white;
      color: var(--muted);
      border-radius: 999px;
      padding: 7px 12px;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
    }
    .chip.active { color: var(--brand); border-color: oklch(82% 0.07 250); background: oklch(97% 0.02 250); }

    .toolbar { display: flex; gap: 8px; align-items: center; }
    .btn {
      border: 1px solid var(--border);
      background: #fff;
      color: var(--text);
      border-radius: 10px;
      padding: 8px 11px;
      font-weight: 600;
      cursor: pointer;
    }

    .toggle-panel {
      display: none;
      margin-top: 10px;
      border: 1px solid var(--border);
      background: var(--surface-2);
      border-radius: 10px;
      padding: 10px;
      font-size: 13px;
    }
    .toggle-panel.open { display: block; }
    .toggle-grid { display: flex; gap: 14px; flex-wrap: wrap; }
    label { display: flex; align-items: center; gap: 6px; color: var(--muted); }

    .table-wrap { overflow: auto; }
    table { width: 100%; border-collapse: collapse; min-width: 1320px; }
    thead th {
      text-align: left;
      font-size: 12px;
      color: var(--muted);
      padding: 10px 10px;
      background: var(--surface);
      position: sticky; top: 0;
      z-index: 2;
      border-bottom: 1px solid var(--border);
      white-space: nowrap;
    }
    tbody td {
      padding: 11px 10px;
      border-bottom: 1px solid oklch(93% 0.008 255);
      font-size: 13px;
      white-space: nowrap;
    }
    tbody tr:hover { background: oklch(97.5% 0.008 250); }

    .right { text-align: right; }
    .center { text-align: center; }

    .asset {
      display: flex; align-items: center; gap: 10px;
    }
    .coin-icon {
      width: 26px; height: 26px; border-radius: 50%;
      background: linear-gradient(145deg, oklch(75% 0.08 260), oklch(64% 0.12 250));
      color: white; display: grid; place-items: center; font-size: 11px; font-weight: 700;
      flex-shrink: 0;
    }
    .asset-name { font-weight: 600; }
    .sym { color: var(--muted); font-size: 12px; margin-left: 4px; }

    .spark { width: 120px; height: 34px; }

    .index-row td {
      background: oklch(98% 0.02 245);
      border-bottom-color: oklch(88% 0.03 245);
      font-weight: 600;
    }

    .pagination {
      display: flex; align-items: center; gap: 8px;
      padding: 12px 14px 16px;
      flex-wrap: wrap;
      border-top: 1px solid var(--border);
    }
    .page {
      min-width: 30px; height: 30px; border-radius: 8px; border: 1px solid var(--border);
      background: #fff; color: var(--muted); display: grid; place-items: center;
      cursor: pointer; font-size: 13px; font-weight: 600;
    }
    .page.active { color: #fff; border-color: var(--brand); background: var(--brand); }

    .two-col { display: grid; grid-template-columns: 1fr; gap: 14px; margin-top: 14px; }
    .summary, .info, footer { padding: 16px; }
    .summary h2, .info h2 { margin: 0 0 8px; font-size: 18px; }
    .summary p, .info p, .info li { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.55; }
    .more { color: var(--brand); background: none; border: 0; padding: 0; cursor: pointer; font-weight: 650; }

    .footer-links { display: flex; gap: 16px; flex-wrap: wrap; margin-top: 8px; }
    .footer-links a { color: var(--muted); text-decoration: none; font-size: 13px; }

    @media (max-width: 1000px) {
      .topbar-inner { height: auto; padding: 10px 0; align-items: flex-start; flex-direction: column; }
      h1 { font-size: 22px; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container topbar-inner">
      <div class="brand"><div class="logo">CT</div><span>CoinTracker Pro</span></div>
      <nav class="nav">
        <a href="index.html" class="active">Cryptocurrencies</a>
        <a href="index.html">Dashboards</a>
        <a href="index.html">Exchanges</a>
        <a href="index.html">DexScan</a>
      </nav>
    </div>
  </header>

  <div class="market-strip">
    <div class="container">
      <div class="stat-item">Market Cap: <b class="mono">$2.56T</b> <span class="up pct">1.46%</span></div>
      <div class="stat-item">CMC20: <b class="mono">57</b> <span class="up pct">0.22%</span></div>
      <div class="stat-item">Fear &amp; Greed: <b>Neutral</b> <b class="mono">37/100</b></div>
      <div class="stat-item">BTC Dominance: <b class="mono">59.04%</b></div>
      <div class="stat-item">24h Volume: <b class="mono">$156.9B</b></div>
    </div>
  </div>

  <main class="container">
    <section class="promo-wrap">
      <div class="promo" id="promoBanner">
        <button class="arrow left" id="promoPrev">‹</button>
        <div class="slides" id="promoSlides">
          <article class="slide">
            <div><h3>Track smarter with CoinTracker AI Alerts</h3><p>Instant unusual-volume and volatility signals for your watchlist.</p></div>
            <button class="cta">Enable Alerts</button>
          </article>
          <article class="slide">
