            <button class="cta">Open Portfolio</button>
          </article>
          <article class="slide">
            <div><h3>Institutional-grade APIs now included</h3><p>Get faster snapshots and historical candles with lower latency.</p></div>
            <button class="cta">View Plans</button>
          </article>
        </div>
        <button class="arrow right" id="promoNext">›</button>
