        <div class="chip-row" id="categoryTabs"></div>
        <div class="chip-row" id="networkTabs"></div>

        <div class="toggle-panel" id="columnsPanel"><div class="toggle-grid" id="columnToggles"></div></div>
        <div class="toggle-panel" id="filtersPanel">
          <div class="toggle-grid">
            <label><input type="checkbox" id="onlyGainers" /> 24h gainers only</label>
