          </div>
        </div>
      </div>

      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th data-col="rank">#</th>
              <th data-col="name">Name</th>
              <th class="right" data-col="price">Price</th>
              <th class="right" data-col="h1">1h %</th>
              <th class="right" data-col="h24">24h %</th>
              <th class="right" data-col="d7">7d %</th>
              <th class="right" data-col="mcap">Market Cap</th>
              <th class="right" data-col="vol">Volume(24h)</th>
              <th class="right" data-col="supply">Circulating Supply</th>
              <th class="center" data-col="spark">Last 7 Days</th>
            </tr>
          </thead>
          <tbody id="tableBody"></tbody>
        </table>
