  </main>

  <script>
    const categories = ["Top", "Trending", "Watchlist", "Prediction Markets", "Most Visited", "New"];
    const networks = ["All Networks", "BSC", "Solana", "Base", "Ethereum", "More"];

    const seedNames = [
      ["Bitcoin","BTC"], ["Ethereum","ETH"], ["Tether","USDT"], ["XRP","XRP"], ["BNB","BNB"], ["Solana","SOL"], ["USDC","USDC"], ["Cardano","ADA"], ["Dogecoin","DOGE"], ["TRON","TRX"],
      ["Toncoin","TON"], ["Chainlink","LINK"], ["Polygon","POL"], ["Polkadot","DOT"], ["Litecoin","LTC"], ["Avalanche","AVAX"], ["Shiba Inu","SHIB"], ["Bitcoin Cash","BCH"], ["Uniswap","UNI"], ["NEAR Protocol","NEAR"],
      ["Internet Computer","ICP"], ["Aptos","APT"], ["Render","RNDR"], ["Arbitrum","ARB"], ["Optimism","OP"], ["Stellar","XLM"], ["Kaspa","KAS"], ["Sui","SUI"], ["VeChain","VET"], ["Hedera","HBAR"]
    ];

    const chainMap = ["Ethereum","Ethereum","Ethereum","Ethereum","BSC","Solana","Ethereum","Ethereum","Ethereum","BSC","Ethereum","Ethereum","Ethereum","Ethereum","Ethereum","Ethereum","Ethereum","BSC","Ethereum","Ethereum","Ethereum","Ethereum","Base","Base","Base","Ethereum","More","Solana","More","More"];

    function fmtMoney(n, d = 2) {
      return '$' + n.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
    }
    function fmtNum(n, d = 2) {
      return n.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
    }
    function pct(v) {
      const sign = v > 0 ? '+' : '';
      return `<span class="pct ${v >= 0 ? 'up' : 'down'}">${sign}${fmtNum(v,2)}%</span>`;
    }

    const rows = Array.from({ length: 100 }, (_, i) => {
      const rank = i + 1;
      const base = seedNames[i % seedNames.length];
      const name = i < 30 ? base[0] : `${base[0]} ${Math.floor(i/30)+1}`;
      const symbol = i < 30 ? base[1] : `${base[1]}${Math.floor(i/30)+1}`;
      const network = chainMap[i % chainMap.length];
      let price = Math.max(0.00001, 75612.78 / Math.pow(rank, 1.18));
      if (rank === 2) price = 2356.00;
      if (rank === 1) price = 75612.78;
      if (rank === 30) price = 88.25;
      const h1 = ((Math.sin(rank * 1.7) * 1.8) + (rank % 2 ? 0.2 : -0.2));
      const h24 = (Math.cos(rank * 0.91) * 5.1);
      const d7 = (Math.sin(rank * 0.44) * 12.4);
      const mcap = rank === 1 ? 1.51e12 : Math.max(45e6, (1.51e12 / Math.pow(rank, 1.08)));
      const vol = rank === 1 ? 28.435e10 : Math.max(2e6, mcap * (0.025 + (rank % 8) * 0.005));
      const supply = rank === 1 ? '20.01M BTC' : `${fmtNum(Math.max(1.2, 85 / rank), 2)}M ${symbol}`;

      const category =
        rank <= 40 ? 'Top' :
        rank % 5 === 0 ? 'Trending' :
        rank % 7 === 0 ? 'Watchlist' :
        rank % 11 === 0 ? 'Prediction Markets' :
        rank % 3 === 0 ? 'Most Visited' : 'New';

      return { rank, name, symbol, price, h1, h24, d7, mcap, vol, supply, category, network };
    });

    const tableBody = document.getElementById('tableBody');
    const pagination = document.getElementById('pagination');
    const categoryTabs = document.getElementById('categoryTabs');
    const networkTabs = document.getElementById('networkTabs');

    let activeCategory = 'Top';
    let activeNetwork = 'All Networks';
    let currentPage = 1;
    const perPage = 100;

    const columnState = {
      rank: true, name: true, price: true, h1: true, h24: true, d7: true, mcap: true, vol: true, supply: true, spark: true
    };

    function sparkline(seed, positive = true) {
      const points = Array.from({length: 14}, (_, i) => {
        const x = i / 13;
        const y = 18 + Math.sin(seed * 0.2 + i * 0.65) * 8 + (positive ? -x*5 : x*5);
        return `${(x*118+1).toFixed(1)},${y.toFixed(1)}`;
      }).join(' ');
      const color = positive ? 'var(--positive)' : 'var(--negative)';
      return `<svg class="spark" viewBox="0 0 120 36" preserveAspectRatio="none"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round"/></svg>`;
    }

    function buildTabs() {
      categoryTabs.innerHTML = categories.map(c => `<button class="chip ${c === activeCategory ? 'active' : ''}" data-cat="${c}">${c}</button>`).join('');
      networkTabs.innerHTML = networks.map(n => `<button class="chip ${n === activeNetwork ? 'active' : ''}" data-net="${n}">${n}</button>`).join('');

      categoryTabs.querySelectorAll('[data-cat]').forEach(btn => btn.addEventListener('click', () => {
        activeCategory = btn.dataset.cat;
        currentPage = 1;
        buildTabs(); render();
      }));
      networkTabs.querySelectorAll('[data-net]').forEach(btn => btn.addEventListener('click', () => {
        activeNetwork = btn.dataset.net;
        currentPage = 1;
        buildTabs(); render();
      }));
    }

    function filteredRows() {
      const gainers = document.getElementById('onlyGainers').checked;
      const hideStable = document.getElementById('hideStable').checked;
      const over1b = document.getElementById('over1bCap').checked;

      return rows.filter(r => {
        const byCategory = activeCategory === 'Top' ? r.rank <= 100 : r.category === activeCategory;
        const byNetwork = activeNetwork === 'All Networks' || activeNetwork === 'More' ? (activeNetwork === 'More' ? !['BSC','Solana','Base','Ethereum'].includes(r.network) : true) : r.network === activeNetwork;
        const byGainers = !gainers || r.h24 > 0;
        const byStable = !hideStable || !['USDT','USDC'].includes(r.symbol.replace(/[0-9]/g, ''));
        const byCap = !over1b || r.mcap > 1e9;
        return byCategory && byNetwork && byGainers && byStable && byCap;
      });
    }

    function render() {
      const list = filteredRows();
      const pages = Math.max(84, Math.ceil(list.length / perPage));
      const start = (currentPage - 1) * perPage;
      const pageRows = list.slice(start, start + perPage);

      const idx = {
        name: 'CoinTracker 20 Index', symbol: 'CT20', price: 154.29, h1: 0.21, h24: 1.15, d7: 4.97, mcap: null, vol: null, supply: '-', rank: '—'
      };

      const indexRow = `
        <tr class="index-row">
          <td data-col="rank" class="center">${idx.rank}</td>
          <td data-col="name"><div class="asset"><div class="coin-icon">20</div><div><span class="asset-name">${idx.name}</span> <span class="sym">${idx.symbol}</span></div></div></td>
          <td data-col="price" class="right mono">${fmtMoney(idx.price)}</td>
          <td data-col="h1" class="right">${pct(idx.h1)}</td>
          <td data-col="h24" class="right">${pct(idx.h24)}</td>
          <td data-col="d7" class="right">${pct(idx.d7)}</td>
          <td data-col="mcap" class="right mono">—</td>
          <td data-col="vol" class="right mono">—</td>
          <td data-col="supply" class="right mono">${idx.supply}</td>
          <td data-col="spark" class="center">${sparkline(9, true)}</td>
        </tr>`;

      tableBody.innerHTML = indexRow + pageRows.map(r => `
        <tr>
          <td data-col="rank" class="center mono">${r.rank}</td>
          <td data-col="name">
            <div class="asset">
              <div class="coin-icon">${r.symbol.slice(0,2)}</div>
              <div><span class="asset-name">${r.name}</span> <span class="sym">${r.symbol}</span></div>
            </div>
          </td>
          <td data-col="price" class="right mono">${fmtMoney(r.price, r.price < 1 ? 5 : 2)}</td>
          <td data-col="h1" class="right">${pct(r.h1)}</td>
          <td data-col="h24" class="right">${pct(r.h24)}</td>
          <td data-col="d7" class="right">${pct(r.d7)}</td>
          <td data-col="mcap" class="right mono">${fmtMoney(r.mcap,0)}</td>
          <td data-col="vol" class="right mono">${fmtMoney(r.vol,0)}</td>
          <td data-col="supply" class="right mono">${r.supply}</td>
          <td data-col="spark" class="center">${sparkline(r.rank, r.d7 >= 0)}</td>
        </tr>`).join('');

      pagination.innerHTML = [1,2,3,4,'…',84].map(p => typeof p === 'number'
        ? `<button class="page ${currentPage===p?'active':''}" data-page="${p}">${p}</button>`
        : `<span class="page" style="cursor:default">${p}</span>`).join('');

      pagination.querySelectorAll('[data-page]').forEach(btn => btn.addEventListener('click', () => {
        currentPage = Number(btn.dataset.page);
        render();
      }));

      Object.keys(columnState).forEach(key => {
        document.querySelectorAll(`[data-col="${key}"]`).forEach(el => {
          el.style.display = columnState[key] ? '' : 'none';
        });
      });
    }

    function initColumnToggles() {
      const labels = {
        rank:'#', name:'Name', price:'Price', h1:'1h%', h24:'24h%', d7:'7d%', mcap:'Market Cap', vol:'Volume(24h)', supply:'Circulating Supply', spark:'7D Sparkline'
      };
