          <td data-col="supply" class="right mono">${idx.supply}</td>
          <td data-col="spark" class="center">${sparkline(9, true)}</td>
        </tr>`;

      tableBody.innerHTML = indexRow + pageRows.map(r => `
        <tr>
          <td data-col="rank" class="center mono">${r.rank}</td>
          <td data-col="name">
            <div class="asset">
              <div class="coin-icon">${r.symbol.slice(0,2)}</div>
              <div><span class="asset-name">${r.name}</span> <span class="sym">${r.symbol}</span></div>
            </div>
          </td>
          <td data-col="price" class="right mono">${fmtMoney(r.price, r.price < 1 ? 5 : 2)}</td>
          <td data-col="h1" class="right">${pct(r.h1)}</td>
          <td data-col="h24" class="right">${pct(r.h24)}</td>
          <td data-col="d7" class="right">${pct(r.d7)}</td>
          <td data-col="mcap" class="right mono">${fmtMoney(r.mcap,0)}</td>
          <td data-col="vol" class="right mono">${fmtMoney(r.vol,0)}</td>
          <td data-col="supply" class="right mono">${r.supply}</td>
          <td data-col="spark" class="center">${sparkline(r.rank, r.d7 >= 0)}</td>
        </tr>`).join('');

      pagination.innerHTML = [1,2,3,4,'…',84].map(p => typeof p === 'number'
        ? `<button class="page ${currentPage===p?'active':''}" data-page="${p}">${p}</button>`
        : `<span class="page" style="cursor:default">${p}</span>`).join('');

      pagination.querySelectorAll('[data-page]').forEach(btn => btn.addEventListener('click', () => {
        currentPage = Number(btn.dataset.page);
        render();
      }));

      Object.keys(columnState).forEach(key => {
        document.querySelectorAll(`[data-col="${key}"]`).forEach(el => {
          el.style.display = columnState[key] ? '' : 'none';
        });
      });
    }

    function initColumnToggles() {
      const labels = {
        rank:'#', name:'Name', price:'Price', h1:'1h%', h24:'24h%', d7:'7d%', mcap:'Market Cap', vol:'Volume(24h)', supply:'Circulating Supply', spark:'7D Sparkline'
      };
      const wrap = document.getElementById('columnToggles');
      wrap.innerHTML = Object.keys(labels).map(k => `<label><input type="checkbox" data-col-toggle="${k}" ${columnState[k]?'checked':''}/> ${labels[k]}</label>`).join('');
      wrap.querySelectorAll('[data-col-toggle]').forEach(chk => chk.addEventListener('change', () => {
        columnState[chk.dataset.colToggle] = chk.checked;
        render();
      }));
    }

    document.getElementById('columnsBtn').addEventListener('click', () => {
      document.getElementById('columnsPanel').classList.toggle('open');
    });
    document.getElementById('filtersBtn').addEventListener('click', () => {
      document.getElementById('filtersPanel').classList.toggle('open');
    });
    document.querySelectorAll('#filtersPanel input').forEach(i => i.addEventListener('change', () => {
      currentPage = 1; render();
    }));

    const summaryShort = document.getElementById('summaryText').innerHTML;
    const summaryLong = summaryShort + ' In derivatives markets, open interest has risen across BTC and ETH perpetuals while funding remains balanced, suggesting selective risk-on positioning rather than broad speculative excess. Mid-cap layer-1 assets outperformed large caps over the last week, though liquidity remains concentrated in BTC, ETH, and stablecoin pairs.';
    let expanded = false;
    document.getElementById('readMoreBtn').addEventListener('click', () => {
      expanded = !expanded;
      document.getElementById('summaryText').innerHTML = expanded ? summaryLong : summaryShort;
      document.getElementById('readMoreBtn').textContent = expanded ? 'Read Less' : 'Read More';
    });

    let slideIndex = 0;
    const promoSlides = document.getElementById('promoSlides');
    const totalSlides = promoSlides.children.length;
    const updateSlides = () => promoSlides.style.transform = `translateX(-${slideIndex * 100}%)`;
    document.getElementById('promoPrev').addEventListener('click', () => { slideIndex = (slideIndex - 1 + totalSlides) % totalSlides; updateSlides(); });
    document.getElementById('promoNext').addEventListener('click', () => { slideIndex = (slideIndex + 1) % totalSlides; updateSlides(); });
    setInterval(() => { slideIndex = (slideIndex + 1) % totalSlides; updateSlides(); }, 5000);

    buildTabs();
    initColumnToggles();
    render();
  </script>
</body>
